$ErrorActionPreference = "Stop"

Write-Host "=== SaborFlow - Correcao do Security Panel Etapa 13.3 ===" -ForegroundColor Cyan
Write-Host ""

if (-not (Test-Path "package.json")) {
    throw "Execute este script na pasta principal do projeto SaborFlow."
}

$target = "components\admin\security-panel.tsx"

if (-not (Test-Path $target)) {
    throw "Arquivo nao encontrado: $target"
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backup = Join-Path $env:TEMP "security-panel-antes-correcao-$timestamp.tsx"
Copy-Item $target $backup -Force

$bytes = [Convert]::FromBase64String("")
[IO.File]::WriteAllBytes((Join-Path (Get-Location) $target), $bytes)

Write-Host "Security Panel corrigido." -ForegroundColor Green
Write-Host "Backup criado em:" -ForegroundColor Green
Write-Host $backup
Write-Host ""
Write-Host "Nenhuma migration foi executada." -ForegroundColor Yellow
Write-Host "Nenhum commit ou deploy foi feito." -ForegroundColor Yellow
Write-Host ""
git status --short
